import{_ as d,a0 as p,w as o,s as u,I as e,x as n,a1 as t,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20200204 Managing your attached hardware on Linux with systemd-udevd","title":"在 Linux 使用 systemd-udevd 管理你的接入硬件","tag":"202108","desc":""},"relativePath":"202108/20200204 Managing your attached hardware on Linux with systemd-udevd.md","filePath":"[post].md"}'),r={name:"202108/20200204 Managing your attached hardware on Linux with systemd-udevd.md"};function g(f,s,b,c,k,m){const a=p("Link");return o(),u("div",null,[s[38]||(s[38]=e("h1",{id:"在-linux-使用-systemd-udevd-管理你的接入硬件",tabindex:"-1"},[n("在 Linux 使用 systemd-udevd 管理你的接入硬件 "),e("a",{class:"header-anchor",href:"#在-linux-使用-systemd-udevd-管理你的接入硬件","aria-label":"Permalink to “在 Linux 使用 systemd-udevd 管理你的接入硬件”"},"​")],-1)),s[39]||(s[39]=e("blockquote",null,[e("p",null,"使用 udev 管理你的 Linux 系统处理物理设备的方式。")],-1)),s[40]||(s[40]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/17/104654z1evcdx41xfc4zpq.jpg",alt:""})],-1)),s[41]||(s[41]=e("p",null,"Linux 能够出色地自动识别、加载、并公开接入的无数厂商的硬件设备。事实上，很多年以前，正是这个特性说服我，坚持让我的雇主将整个基础设施转换到 Linux。痛点在于 Redmond 的某家公司（LCTT 译注：指微软）不能在我们的 Compaq 台式机上加载集成网卡的驱动，而 Linux 可以轻松实现这一点。",-1)),e("p",null,[s[1]||(s[1]=n("从那以后的岁月里，Linux 的识别设备库随着该过程的复杂化而与日俱增，而 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Udev"},{default:i(()=>[...s[0]||(s[0]=[n("udev",-1)])]),_:1}),s[2]||(s[2]=n(" 就是解决这个问题的希望之星。udev 负责监听 Linux 内核发出的改变设备状态的事件。它可能是一个新 USB 设备被插入或拔出，也可能是一个无线鼠标因浸入洒出的咖啡中而脱机。",-1))]),e("p",null,[s[4]||(s[4]=n("udev 负责处理所有的状态变更，比如指定访问设备使用的名称和权限。这些更改的记录可以通过 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Dmesg"},{default:i(()=>[...s[3]||(s[3]=[n("dmesg",-1)])]),_:1}),s[5]||(s[5]=n(" 获取。由于 dmesg 的输出通常有几千行，对结果进行过滤通常是聪明的选择。下面的例子说明了 Linux 如何识别我的 WiFi 接口。这个例子展示了我的无线设备使用的芯片组（",-1)),s[6]||(s[6]=e("code",null,"ath9k",-1)),s[7]||(s[7]=n("）、启动过程早期阶段分配的原始名称（",-1)),s[8]||(s[8]=e("code",null,"wlan0",-1)),s[9]||(s[9]=n("）、以及正在使用的又臭又长的永久名称（",-1)),s[10]||(s[10]=e("code",null,"wlxec086b1ef0b3",-1)),s[11]||(s[11]=n("）：",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dmesg | grep wlan</span></span>
<span class="line"><span>[    5.396874] ath9k_htc 1-3:1.0 wlxec086b1ef0b3: renamed from wlan0</span></span></code></pre></div>`,1)),e("p",null,[s[13]||(s[13]=n("在这篇文章中，我会讨论为何有人想要使用这样的名称。在这个过程中，我会探索剖析 udev 的配置文件，然后展示如何更改 udev 的设置，包括编辑系统命名设备的方式。这篇文件基于我的新课程中《",-1)),t(a,{href:"https://pluralsight.pxf.io/RqrJb"},{default:i(()=>[...s[12]||(s[12]=[n("Linux 系统优化",-1)])]),_:1}),s[14]||(s[14]=n("》的一个模块。",-1))]),s[43]||(s[43]=l(`<h3 id="理解-udev-配置系统" tabindex="-1">理解 udev 配置系统 <a class="header-anchor" href="#理解-udev-配置系统" aria-label="Permalink to “理解 udev 配置系统”">​</a></h3><p>使用 systemd 的机器上，udev 操作由 <code>systemd-udevd</code> 守护进程管理，你可以通过常规的 systemd 方式使用 <code>systemctl status systemd-udevd</code> 检查 udev 守护进程的状态。</p><p>严格来说，udev 的工作方式是试图将它收到的每个系统事件与 <code>/lib/udev/rules.d/</code> 和 <code>/etc/udev/rules.d/</code> 目录下找到的规则集进行匹配。规则文件包括匹配键和分配键，可用的匹配键包括 <code>action</code>、<code>name</code> 和 <code>subsystem</code>。这意味着如果探测到一个属于某个子系统的、带有特定名称的设备，就会给设备指定一个预设的配置。</p><p>接着，“分配”键值对被拿来应用想要的配置。例如，你可以给设备分配一个新名称、将其关联到文件系统中的一个符号链接、或者限制为只能由特定的所有者或组访问。这是从我的工作站摘出的一条规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /lib/udev/rules.d/73-usb-net-by-mac.rules</span></span>
<span class="line"><span># Use MAC based names for network interfaces which are directly or indirectly</span></span>
<span class="line"><span># on USB and have an universally administered (stable) MAC address (second bit</span></span>
<span class="line"><span># is 0). Don&#39;t do this when ifnames is disabled via kernel command line or</span></span>
<span class="line"><span># customizing/disabling 99-default.link (or previously 80-net-setup-link.rules).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMPORT{cmdline}=&quot;net.ifnames&quot;</span></span>
<span class="line"><span>ENV{net.ifnames}==&quot;0&quot;, GOTO=&quot;usb_net_by_mac_end&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;net&quot;, SUBSYSTEMS==&quot;usb&quot;, NAME==&quot;&quot;, \\</span></span>
<span class="line"><span>    ATTR{address}==&quot;?[014589cd]:*&quot;, \\</span></span>
<span class="line"><span>    TEST!=&quot;/etc/udev/rules.d/80-net-setup-link.rules&quot;, \\</span></span>
<span class="line"><span>    TEST!=&quot;/etc/systemd/network/99-default.link&quot;, \\</span></span>
<span class="line"><span>    IMPORT{builtin}=&quot;net_id&quot;, NAME=&quot;$env{ID_NET_NAME_MAC}&quot;</span></span></code></pre></div><p><code>add</code> 动作告诉 udev，只要新插入的设备属于网络子系统，<em>并且</em>是一个 USB 设备，就执行操作。此外，如果我理解正确的话，只有设备的 MAC 地址由特定范围内的字符组成，并且 <code>80-net-setup-link.rules</code> 和 <code>99-default.link</code> 文件<em>不</em>存在时，规则才会生效。</p><p>假定所有的条件都满足，接口 ID 会改变以匹配设备的 MAC 地址。还记得之前的 dmesg 信息显示我的接口名称从 <code>wlan0</code> 改成了讨厌的 <code>wlxec086b1ef0b3</code> 吗？那都是这条规则的功劳。我怎么知道？因为 <code>ec:08:6b:1e:f0:b3</code> 是设备的 MAC 地址（不包括冒号）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig -a</span></span>
<span class="line"><span>wlxec086b1ef0b3: flags=4163&lt;UP,BROADCAST,RUNNING,MULTICAST&gt;  mtu 1500</span></span>
<span class="line"><span>        inet 192.168.0.103  netmask 255.255.255.0  broadcast 192.168.0.255</span></span>
<span class="line"><span>        inet6 fe80::7484:3120:c6a3:e3d1  prefixlen 64  scopeid 0x20&lt;link&gt;</span></span>
<span class="line"><span>        ether ec:08:6b:1e:f0:b3  txqueuelen 1000  (Ethernet)</span></span>
<span class="line"><span>        RX packets 682098  bytes 714517869 (714.5 MB)</span></span>
<span class="line"><span>        RX errors 0  dropped 0  overruns 0  frame 0</span></span>
<span class="line"><span>        TX packets 472448  bytes 201773965 (201.7 MB)</span></span>
<span class="line"><span>        TX errors 0  dropped 0 overruns 0  carrier 0  collisions 0</span></span></code></pre></div><p>Linux 默认包含这条 udev 规则，我不需要自己写。但是为什么费力进行这样的命名呢——尤其是看到这样的接口命名这么难使用后？仔细看一下包含在规则中的注释：</p><blockquote><p>对直接或间接插入在 USB 上的网络接口使用基于 MAC 的名称，并且用一个普遍提供的（稳定的）MAC 地址（第二位是 0）。当 ifnames 通过内核命令行或 <code>customizing/disabling 99-default.link</code>（或之前的 <code>80-net-setup-link.rules</code>）被禁用时，不要这样做。</p></blockquote><p>注意，这个规则专为基于 USB 的网络接口设计的。和 PCI 网络接口卡（NIC）不同，USB 设备很可能时不时地被移除或者替换，这意味着无法保证它们的 ID 不变。某一天 ID 可能是 <code>wlan0</code>，第二天却变成了 <code>wlan3</code>。为了避免迷惑应用程序，指定绝对 ID 给设备——就像分配给我的 USB 接口的 ID。</p><h3 id="操作-udev-的设置" tabindex="-1">操作 udev 的设置 <a class="header-anchor" href="#操作-udev-的设置" aria-label="Permalink to “操作 udev 的设置”">​</a></h3>`,12)),e("p",null,[s[16]||(s[16]=n("下一个示例中，我将从 ",-1)),t(a,{href:"https://www.virtualbox.org/"},{default:i(()=>[...s[15]||(s[15]=[n("VirtualBox",-1)])]),_:1}),s[17]||(s[17]=n(" 虚拟机里抓取以太网接口的 MAC 地址和当前接口 ID，然后用这些信息创建一个改变接口 ID 的 udev 新规则。为什么这么做？也许我打算从命令行操作设备，需要输入那么长的名称让人十分烦恼。下面是工作原理。",-1))]),e("p",null,[s[19]||(s[19]=n("改变接口 ID 之前，我需要关闭 ",-1)),t(a,{href:"https://netplan.io/"},{default:i(()=>[...s[18]||(s[18]=[n("Netplan",-1)])]),_:1}),s[20]||(s[20]=n(" 当前的网络配置，促使 Linux 使用新的配置。下面是 ",-1)),s[21]||(s[21]=e("code",null,"/etc/netplan/",-1)),s[22]||(s[22]=n(" 目录下我的当前网络接口配置文件：",-1))]),s[44]||(s[44]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less /etc/netplan/50-cloud-init.yaml</span></span>
<span class="line"><span># This file is generated from information provided by</span></span>
<span class="line"><span># the datasource.  Changes to it will not persist across an instance.</span></span>
<span class="line"><span># To disable cloud-init&#39;s network configuration capabilities, write a file</span></span>
<span class="line"><span># /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg with the following:</span></span>
<span class="line"><span># network: {config: disabled}</span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>        enp0s3:</span></span>
<span class="line"><span>            addresses: []</span></span>
<span class="line"><span>            dhcp4: true</span></span>
<span class="line"><span>    version: 2</span></span></code></pre></div><p><code>50-cloud-init.yaml</code> 文件包含一个非常基本的接口定义，但是注释中也包含一些禁用配置的重要信息。为此，我将移动到 <code>/etc/cloud/cloud.cfg.d</code> 目录，创建一个名为 <code>/etc/cloud/cloud.cfg.d</code> 的新文件，插入 <code>network: {config: disabled}</code> 字符串。</p><p>尽管我只在 Ubuntu 发行版上测试了这个方法，但它应该在任何一个带有 systemd 的 Linux（几乎所有的 Linux 发行版都有 systemd）上都可以工作。不管你使用哪个，都可以很好地了解编写 udev 配置文件并对其进行测试。</p><p>接下来，我需要收集一些系统信息。执行 <code>ip</code> 命令，显示我的以太网接口名为 <code>enp0s3</code>，MAC 地址是 <code>08:00:27:1d:28:10</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span>
<span class="line"><span>2: enp0s3: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:1d:28:10 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 192.168.0.115/24 brd 192.168.0.255 scope global dynamic enp0s3</span></span></code></pre></div><p>现在，我要在 <code>/etc/udev/rules.d</code> 目录创建一个名为 <code>peristent-net.rules</code> 的新文件。我将给文件一个以较小的数字开头的名称，比如 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/udev/rules.d/10-persistent-network.rules</span></span>
<span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;net&quot;,ATTR{address}==&quot;08:00:27:1d:28:10&quot;,NAME=&quot;eth3&quot;</span></span></code></pre></div><p>数字越小，Linux 越早执行文件，我想要这个文件早点执行。文件被添加时，包含其中的代码就会分配名称 <code>eth3</code> 给网络设备——只要设备的地址能够匹配 <code>08:00:27:1d:28:10</code>，即我的接口的 MAC 地址 。</p><p>保存文件并重启计算机后，我的新接口名应该就会生效。我可能需要直接登录虚拟机，使用 <code>dhclient</code> 手动让 Linux 为这个新命名的网络请求一个 IP 地址。在执行下列命令前，可能无法打开 SSH 会话：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dhclient eth3</span></span></code></pre></div><p>大功告成。现在你能够促使 udev 控制计算机按照你想要的方式指向一个网卡，但更重要的是，你已经有了一些工具，可以弄清楚如何管理任何不听话的设备。</p><hr>`,12)),e("p",null,[s[24]||(s[24]=n("via: ",-1)),t(a,{href:"https://opensource.com/article/20/2/linux-systemd-udevd"},{default:i(()=>[...s[23]||(s[23]=[n("https://opensource.com/article/20/2/linux-systemd-udevd",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/dbclinton"},{default:i(()=>[...s[25]||(s[25]=[n("David Clinton",-1)])]),_:1}),s[30]||(s[30]=n(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[n("lujun9972",-1)])]),_:1}),s[31]||(s[31]=n(" 译者：",-1)),t(a,{href:"https://github.com/YungeG"},{default:i(()=>[...s[27]||(s[27]=[n("YungeG",-1)])]),_:1}),s[32]||(s[32]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[n("LCTT",-1)])]),_:1}),s[36]||(s[36]=n(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[n("Linux中国",-1)])]),_:1}),s[37]||(s[37]=n(" 荣誉推出",-1))])])}const T=d(r,[["render",g]]);export{x as __pageData,T as default};
